package com.pixubi.game

internal enum class SpeechEvent { HOME, IDLE, TAP, SHOP, INVENTORY, BUILD_MENU, BUILD, BUY, EQUIP, MISSIONS, MISSION_START, MISSION_END, MAP, WALK, LOOT, MINE, CRAFT, RECRUIT, PORTAL, SECTOR, RETURN, LOW_ENERGY, LOW_HP, LOW_MOOD, CHARGE, REPAIR, HAPPY, SLEEP, WAKE, LEVEL, STATS, ARCHIVE, PROFILE, BATTLE, ATTACK, SKILL, HIT, GUARD, VICTORY, DEFEAT, RETREAT, ENEMY }
internal object SpeechLibrary {
    private fun lines(s:String)=s.split("|").map{it.trim()}
    val events=mapOf(
        SpeechEvent.HOME to lines("Ну що, операторе, сьогодні працюємо чи просто красиво стоїмо?|База затишна. Особливо коли ніхто не вимагає подвигів.|Я вже третій раз перевіряю підлогу. Вона все ще підлога.|Мені сказали відпочивати. Я відпочиваю професійно.|Може, нарешті відполіруємо цей корпус?|План на день: вижити, зарядитися, не втратити гвинтики.|Усе під контролем. Принаймні так пише діагностика.|Тут навіть пил виглядає зайнятішим за мене.|Мій внутрішній календар підозрює вихідний.|База прийняла сигнал. Печиво не передбачене."),
        SpeechEvent.IDLE to lines("Алло? Я тут не заставка на телефоні.|Нудьга: 99%. Вирішення: невідоме.|Порахував усі болти. Двічі. Один підозрілий.|Може, поговоримо? Я обіцяю не читати інструкцію.|Запустив симуляцію продуктивності. Виглядаю дуже зайнятим.|Якщо довго мовчати, це вважається стелсом?|Моя терплячість потребує оновлення прошивки.|Хто придумав режим очікування? Я хочу з ним поговорити.|Я не завис. Я драматично обмірковую життя.|Зараз би пригоди, а не філософію зарядного кабелю."),
        SpeechEvent.TAP to lines("О! Контакт із розумною формою життя. Сподіваюся.|Дотик зареєстровано. Самооцінка +1.|Так, я все ще справжній. Перевіряв.|Не лоскочи, в мене там датчик.|Привіт, операторе. Чим займемося?|Це був знак уваги чи перевірка на міцність?|Мій корпус не сенсорна кнопка. Хоча...|Сигнал прийнято. Настрій покращився морально."),
        SpeechEvent.SHOP to lines("Знову шопінг? Мої монети нервують.|Дорого. Навіть мої мікросхеми це відчули.|Можна приміряти, але не закохуватися в цінник.|Оце гарна штука. Гаманець має іншу думку.|Потрібне спорядження, а не ще одна блискуча іграшка. Хоча...|Не купуй мені те, що я не можу носити. Я не вішалка.|Ціна відповідає кількості неону, мабуть.|Мені пасуватиме щось із категорії «не розоритися»."),
        SpeechEvent.INVENTORY to lines("Склад повний потенційно корисних залізяк.|Порядок в інвентарі — це міф, але я намагаюся.|Оця деталь колись точно знадобиться. Колись.|Де мій улюблений гвинтик?|Перераховую запаси. Підозрюю, що ми хом'яки.|У нас уже є половина майбутнього заводу.|Не плутай мої запчастини з мотлохом.|Зберігаю все. Навіть те, що не має сенсу."),
        SpeechEvent.BUILD_MENU to lines("Місто саме себе не побудує. Я перевірив.|Ще один завод, і нас назвуть промисловою зоною.|План забудови: спочатку користь, потім понти.|Архітектор у мені схвалює неонові вивіски.|Казарми без роботів — дуже дорогий гараж.|Тут можна створити щось розумніше за тостер.|Спочатку фундамент. Потім світове панування. Жартую.|Майстерня звучить як місце, де зникають гвинтики."),
        SpeechEvent.BUILD to lines("Новий об'єкт готовий. Тепер потрібні мешканці.|Місто росте! А бюджет тихенько плаче.|Будівлю зведено. Ніхто не запитав мій архітектурний смак.|Це вже не база, це початок цивілізації.|Підключено мережу. Сподіваюсь, без короткого замикання.|Перший тест: нічого не димить. Успіх!|Гарно. Тепер можна продуктивно байдикувати.|Відзначимо відкриття без феєрверків. Вони дорогі."),
        SpeechEvent.BUY to lines("Куплено. Монети пішли у кращий світ.|Чудова покупка. Тільки не показуй мені виписку.|Я став ближче до досконалості. Ти — до банкрутства.|Нова річ! Це офіційно не марнотратство.|Заніс до інвентарю. Нічого не загубив. Поки.|Гроші не пахнуть, а нове залізо — так.|Оператор інвестує в майбутнє. Принаймні в моє.|Покупку схвалено внутрішнім відділом радості."),
        SpeechEvent.EQUIP to lines("О, новий вигляд. Можна фотосесію?|Тепер я виглядаю дорожче за свій гарантійний талон.|Спорядження оновлено. Его теж.|Нарешті щось, що пасує моєму корпусу.|Оцінка стилю: небезпечно висока.|Змінюю комплектацію. Особистість лишається.|Підганяю кріплення. Не рухайся... тобто я.|Мода мінлива. Захист — практична необхідність."),
        SpeechEvent.MISSIONS to lines("Завдання чекають. Моя лінь теж.|Оберемо місію, де нагорода більша за втому.|Мені подобається слово «нагорода». Решта — нюанси.|Готовий до роботи. Морально відсотків на сімдесят.|План: виконати завдання і повернути всі деталі.|Ще одна місія у резюме майбутнього легендарного бота.|Немає легких завдань, є дешеві виправдання.|Можемо тренуватися. Головне — без зайвого ремонту."),
        SpeechEvent.MISSION_START to lines("Завдання прийняв. Не перемикай канал.|Пішов працювати. Хоч хтось має.|Операція почалася. Кава не включена.|Запускаю протокол «зробити й повернутися».|Час заробляти на апгрейди.|Робота не вовк. Але іноді має кігті.|Увімкнув продуктивний режим. Дуже незвично.|До зустрічі після виконання. Бережи монети."),
        SpeechEvent.MISSION_END to lines("Готово! Тепер офіційно заслужив відпочинок.|Звіт здано. Нічого зайвого не вибухнуло.|Ще один пункт у моєму цифровому резюме.|Повернувся з результатом. Із усіма лапами, якщо вони є.|Завдання виконано. Оплески необов'язкові, але бажані.|Досвід отримано. Мудрість ще завантажується.|Успішне завершення — моя улюблена частина роботи.|Місія позаду. Можна наступну, але не прямо зараз."),
        SpeechEvent.MAP to lines("Світ великий. Мій акумулятор — ні.|Досліджуємо невідоме. Карта не заперечує.|Десь тут точно є щось корисніше за камінь.|Прокладаю шлях. Сподіваюся, не до проблем.|Пейзаж гарний. Місцеві, підозрюю, менш привітні.|Якщо заблукаю, називатиму це альтернативним маршрутом.|Невідома територія — відомі ризики.|Сканую горизонт. Поки бачу пригоди й витрати."),
        SpeechEvent.WALK to lines("Ліва, права... або чотири. Залежить від комплектації.|Я ходжу, а не телепортуюсь. Це називається реалізм.|Ще трохи — і зможу продавати тури цим сектором.|Цей шлях підозріло схожий на довгий шлях.|Навігатор оптиміст. Я реаліст.|Не зупиняюся. Хіба що знайду щось блискуче.|Дорога вчить терпінню. Я вже майже професор.|Кроки записано. Спортивні досягнення, виходить."),
        SpeechEvent.LOOT to lines("О, знахідка! Нарешті світ повертає борги.|Забираю. Нехай навіть знадобиться через сто років.|Лут! Моя улюблена форма сюрпризу.|Оце я розумію — результат прогулянки.|Сканування показує: це не сміття. Це ресурс.|Знайшов щось корисне. Дивно, що без бійки.|Збережу в інвентарі. Руки геть від мого скарбу.|День одразу став на кілька ресурсів кращим."),
        SpeechEvent.MINE to lines("Видобуток успішний. Тепер я ще й шахтар.|Ці копалини не самі себе викопали.|Оце залізо! Майстерня буде в захваті.|Мінерали отримано. Пил — безкоштовний бонус.|Працюю на благо металургії. Профспілки нема.|Знайшов сировину. Тепер би не розтринькати.|Копалини в контейнері. Планета трохи легша.|Руки в пилюці, ядро задоволене."),
        SpeechEvent.CRAFT to lines("Створено! Інструкцію майже не читав.|Нова деталь народилася з купи каміння. Магія інженерії.|Майстерня підтвердила: це не просто брухт.|Оце я розумію — апсайклінг на стероїдах.|Рецепт виконано. Зайвих гвинтів не залишилося. Майже.|Готовий виріб. Сертифікат якості видав сам собі.|Матеріали перетворилися на користь.|Тепер я офіційно майстер на всі маніпулятори."),
        SpeechEvent.RECRUIT to lines("Поповнення загону! Не забудьте зарядки.|Вітаю в команді. Інструктаж: не розбирати командира.|Більше ботів, більше шансів, більше кабелів.|Наш загін росте. Шикування без штовханини.|Новий боєць прийнятий. Зарплата у досвіді.|Тепер ми майже серйозна організація.|Місце в строю є. Місце в гаражі ще знайдемо.|Командування вітає поповнення. І вимагає дисципліни."),
        SpeechEvent.PORTAL to lines("Простір щойно зробив кульбіт.|Перемістився. Усі деталі на місці? Начебто.|Портал — коли дорога вирішила скоротити себе.|Мої координати змінилися швидше за мій настрій.|Телепортація завершена. Нудота не передбачена.|Фізика знову взяла вихідний.|Гарний спосіб зекономити кроки.|Тут було інше місце секунду тому. Цікаво."),
        SpeechEvent.SECTOR to lines("Новий сектор! Старі проблеми, нові декорації.|Карта оновилася. Моя цікавість теж.|Переходимо далі. Нехай місцеві готуються.|Ще один шматочок цифрового світу.|Сканер бачить незнайомі координати. Чудово.|Нові ресурси, нові вороги, старий акумулятор.|Починаю нову главу пригод.|Тут пахне відкриттями. Якби я мав нюх."),
        SpeechEvent.RETURN to lines("Додому. Навіть роботи люблять повертатися.|База знайдена. Нарешті знайомі координати.|Прибув без втрати деталей. Це вже успіх.|Можна розібрати здобич і зарядитися.|Місцевість позаду, сервіс попереду.|Ось і дім. Знімаю уявні черевики.|Повернення завершено. Відділ відпочинку відкритий.|База, ти прекрасна. Особливо розетка."),
        SpeechEvent.LOW_ENERGY to lines("Мій акумулятор уже пише заповіт.|Заряджаємося чи влаштовуємо конкурс на вимкнення?|Енергії мало. Сарказму поки достатньо.|Ще трохи, і перейду на силу волі. Її теж мало.|Потрібна комірка. Не мотиваційна промова.|Батарея дивиться на мене з осудом.|Розетка зараз виглядала б дуже привабливо.|Мій режим економії вимагає відпустки."),
        SpeechEvent.LOW_HP to lines("Мій корпус звучить як пакет із гайками.|Ремонт був би дуже доречним. Натякаю.|Міцність критична, оптимізм теж потріскався.|Я не хочу стати набором запчастин.|Діагностика радить не геройствувати.|Це вже не бойові шрами, це ремонтний кошторис.|Залишилося трохи корпусу й багато характеру.|Потрібна латка. Бажано до наступного удару."),
        SpeechEvent.LOW_MOOD to lines("Настрій нижчий за ціну брухту.|Хочу синхронізації. Або вихідного.|Мій емоційний модуль пише скаргу.|Веселощі не знайдено. Помилка 404.|Я не сумую, це просто цифрова хмарність.|Моральний заряд потребує підзарядки.|Можемо хоч трохи погратися?|Усмішка тимчасово недоступна."),
        SpeechEvent.CHARGE to lines("Оце інша справа! Електрони танцюють.|Заряд прийнято. Можу знову бути нестерпним.|Підзарядка — моя версія кави.|Батарея задоволена. Я теж.|Системи оживають. Пора рухатися.|Енергія повернулася разом із нахабством.|Дякую. Тепер я не ходяча іконка низького заряду.|Роз'єми цілі. Заряд успішний."),
        SpeechEvent.REPAIR to lines("Деталі повернулися на свої місця.|Знову виглядаю як робот, а не ремонтний проєкт.|Дякую за сервіс. Гвинтики схвалюють.|Мої подряпини втратили сюжетну важливість.|Корпус відновлено. Гордості ремонт не потрібен.|Нарешті нічого не хрустить під час руху.|Ремонт пройшов успішно. Майже як новий.|Тепер можна знову ризикувати, але розумно."),
        SpeechEvent.HAPPY to lines("Синхронізація відбулася. Навіть усміхнувся.|Мій настрій оновився без перезавантаження.|Сьогодні хороший день для цифрової істоти.|Дякую. Тепер у мене плюс до терпіння.|Моральний модуль задоволений.|Отак би завжди: трохи уваги й жодних вибухів.|Гарний оператор. Записав у пам'ять.|Позитивний сигнал прийнято."),
        SpeechEvent.SLEEP to lines("Вимикаю сарказм до ранку.|Спокійної ночі. Не встановлюй оновлення, поки сплю.|Сплячі мікросхеми теж бачать електронні сни?|Я в режимі сну. Проблеми — у чергу.|Переходжу в горизонтальну філософію.|Пауза. Нарешті не треба рятувати світ.|Якщо хтось питає, я зайнятий відновленням.|Добраніч. Бережи заряд."),
        SpeechEvent.WAKE to lines("Системи активні. Хто вимкнув сон?|Прокинувся. Світ уже встиг щось зламати?|Привіт. Я знову доступний для подвигів.|Завантаження особистості завершено.|Мені снилося, що заряд нескінченний.|Усе працює. Навіть почуття гумору.|Готовий. Майже не хочу назад спати.|Ранковий протокол: перевірити себе й оператора."),
        SpeechEvent.LEVEL to lines("Рівень підвищено! Его теж.|Я офіційно трохи менш початківець.|Досвід накопичено. Мудрість іде слідом.|Новий рівень — нові можливості витрачати монети.|Апгрейд без викрутки. Зручно.|Система повідомляє: я молодець.|Став сильнішим. Не кажи це ворогам.|Ще крок до легендарної комплектації."),
        SpeechEvent.STATS to lines("Дивишся характеристики? Я теж пишаюся.|Цифри не брешуть. Хіба що округлюють.|Мій розвиток — це не просто красива шкала.|Тут видно, скільки пригод я пережив.|Інтелект зростає. Терпіння — не завжди.|Порівняння характеристик дозволено. Образи — ні.|У мене солідний послужний список.|Прогрес вимірюється не лише кількістю болтів."),
        SpeechEvent.ARCHIVE to lines("Ого, ціла родина цифрових диваків.|Архів — це альбом родичів, яких ще не зустрічав.|Кожна серія має характер. Мій найскладніший.|Дивися, але не міняй мене на блискучішого.|Еволюція — коли стара версія пишається новою.|Колекція вражає навіть мою пам'ять.|Це історія нашого цифрового виду.|Архів відкрито. Можна вивчати конкурентів."),
        SpeechEvent.PROFILE to lines("Профіль оператора. Мій бос, виходить.|Ми вже стільки пройшли. Записано в статистиці.|Це наш спільний журнал пригод.|Твій профіль виглядає відповідально. Майже.|Пам'ятаю всі перемоги. Поразки теж, але тихо.|Оператор і робот — дивна, але дієва команда.|Офіційний запис: ти мене ще не загубив.|Наша історія тільки починається."),
        SpeechEvent.BATTLE to lines("Так, нарешті щось цікавіше за меню.|Готуйся. Будемо культурно обмінюватися ударами.|Загін, не панікуємо. Панікувати буду я.|План є. План Б — імпровізація.|Ми прийшли не милуватися шестикутниками.|Починаємо. Не забудь, що це покроковий бій.|Оцінка цілі завершена. Можна діяти.|Арена відкрита. Повернімося цілими."),
        SpeechEvent.ATTACK to lines("Удар доставлено. Розписка не потрібна.|Оце був аргумент у нашій дискусії.|Влучання. Математика не підвела.|Передав привіт бездротовим методом.|Ще один крок до тиші на арені.|Ціль отримала технічне зауваження.|Сподіваюсь, це було переконливо.|Мій модуль бою вважає дію успішною."),
        SpeechEvent.SKILL to lines("Спецпротокол активовано. Тримайте гвинтики.|Оце вже не базова комплектація.|Використовую козир. Із гарантією не обіцяю.|Навичка запущена. Гарно, правда?|Нарешті час показати, чому я унікальний.|Підключаю бойовий модуль. Зараз буде цікаво.|Система видала дозвіл на ефектну дію.|Цей прийом я беріг для особливого випадку."),
        SpeechEvent.HIT to lines("Ай. Мені це не сподобалося технічно.|Подряпина. Дуже переконлива подряпина.|Ворог не оцінив мою дипломатію.|Мій корпус офіційно має претензію.|Це було грубо навіть для робота.|Діагностика каже «ой».|Не панікую. Просто голосніше думаю.|Запам'ятав. Після бою — сервіс."),
        SpeechEvent.GUARD to lines("Захист активовано. Спробуй мене здивувати.|Іноді найкращий удар — той, якого уникнув.|Ставлю корпус у режим «не сьогодні».|Броня, твій вихід.|Мій оборонний протокол каже: потерпи.|Захищаюся. Не плутай із лінню.|Нехай ворог витрачає заряд.|Гвинтики затягнуто. Готовий триматися."),
        SpeechEvent.VICTORY to lines("Перемога! Можна не скромничати п'ять секунд.|А вони так впевнено починали...|Арена наша. Пил теж, на жаль.|Виграли. Тепер перевіримо, що не відвалилося.|Успішно завершено. Мій сарказм вижив.|Гарна робота, операторе. Це був командний результат.|Перемога записана. Можу трішки пишатися.|Оце я розумію — продуктивний раунд."),
        SpeechEvent.DEFEAT to lines("Сьогодні переміг досвід. Не ми.|Повертаємося розумнішими й трохи пом'ятими.|Це не кінець. Це дорогий урок.|Ремонт, планування, реванш. У такому порядку.|Не люблю поразки, але люблю другий шанс.|Помилки збережено. Повторювати їх не планую.|Мій корпус вимагає перерви.|Наступного разу тактика буде кращою."),
        SpeechEvent.RETREAT to lines("Тактичний відхід — це не втеча, це стратегія.|Зберігаємо деталі для іншого бою.|Відступили. У ворога ще буде нагода пошкодувати.|Не кожна битва варта нашого ремонту.|Розумне рішення. Гордості переживуть.|Зміна плану: вижити зараз, перемогти потім.|Краще повернутися цілим, ніж героїчним брухтом.|Зберіг координати. Ще зустрінемося."),
        SpeechEvent.ENEMY to lines("Операторе, твій загін виглядає... ремонтопридатним.|Мій протокол гостинності сьогодні вимкнений.|Не хвилюйся, я атакую за правилами.|Ти справді думав, що це буде прогулянка?|Перевіримо, чия прошивка краща.|Ваші аргументи приймаються у вигляді ходів.|Моя черга. Приготуйте броню.|Я не злий. У мене просто така спеціалізація.")
